INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'fill', 2, '{"stem": "填空(1)：8000米+3千米=（ ）米；6米5厘米=（ ）厘米；300分米=（ ）米；（ ）米=20千米。"}', '11000, 605, 30, 20000', '8000+3000=11000; 6×100+5=605; 300÷10=30; 20×1000=20000', 'jsj3_sx_v112', '["jsj3_sx","U789","p077","fill_01"]', 1, NULL);
