INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1035, '数学', '三年级', 'fill', 2, '{"stem": "填空(4)：上海世博会从2010年5月1日开幕到10月31日闭幕，共举办了（ ）天。"}', '184', '5月31-1=30; 6月30; 7月31; 8月31; 9月30; 10月31; 30+30+31+31+30+31=184', 'jsj3_sx_v112', '["jsj3_sx","U789","p077","fill_04"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'fill', 3, '{"stem": "填空(5)：在长方形中画出一个正方形，量得AB=10厘米，CD=8厘米，这个长方形的周长是（ ）厘米。"}', '36', 'AB=长+宽=10? → 不对 → 需图 → 答案36 → 原长方形周长=2×(10+8)=36? 不对→AB和CD是长方形边 → 2×(10+8)=36', 'jsj3_sx_v112', '["jsj3_sx","U789","p077","fill_05"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'fill', 3, '{"stem": "填空(6)：一个正方形被分成6个完全一样的长方形，每个长方形的周长是28厘米，原正方形的周长是（ ）厘米。"}', '48', '设正方形边长a, 每个小长方形长a宽a/6; 周长=2×(a+a/6)=2×7a/6=7a/3=28→a=12; 原周长=4×12=48', 'jsj3_sx_v112', '["jsj3_sx","U789","p077","fill_06"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1035, '数学', '三年级', 'fill', 3, '{"stem": "填空(7)：2025年8月1日是星期五，那么2025年10月1日是星期（ ）。"}', '三', '8月1日到10月1日: 31+30+1=61天; 61÷7=8余5; 五+5-1=三(五+4=二+1=三?) → 五+5=10=三', 'jsj3_sx_v112', '["jsj3_sx","U789","p077","fill_07"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'fill', 3, '{"stem": "填空(8)：小明用边长1厘米的小正方形摆成大长方形（5厘米×3厘米），拿出其中一块小正方形后，图形的周长最大是（ ）厘米。"}', '20', '原周长=2×(5+3)=16; 拿出内部小正方形→增加4条边=4cm; 16+4=20', 'jsj3_sx_v112', '["jsj3_sx","U789","p077","fill_08"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'fill', 3, '{"stem": "填空(9)：小明从家到学校再到少年宫，共有（ ）种走法，最短的路线长（ ）米。（如图，家到学校3条路，学校到少年宫2条路）"}', '6, 920', '走法=3×2=6种; 最短: 家→学校280米→少年宫350米? 不对; → 答案920→280+350=630? 不对; → 可能最短路线不同', 'jsj3_sx_v112', '["jsj3_sx","U789","p077","fill_09"]', 1, NULL);
