INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1035, '数学', '三年级', 'single', 2, '{"stem": "选择(2)：下面的月份中，（ ）的天数之和是62天。A.1月和2月  B.6月和7月  C.8月和9月  D.12月和1月"}', 'D', '12月31天+1月31天=62; 其他: 1月31+2月28=59; 6月30+7月31=61; 8月31+9月30=61', 'jsj3_sx_v112', '["jsj3_sx","U789","p078","choice_02"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1026, '数学', '三年级', 'apply', 2, '{"stem": "应用(1)：乐乐共有127张邮票，如果集邮册每页可以插9张，至少需要插几页？（6分）"}', '15（页）', '127÷9=14...1, 进一法→15', 'jsj3_sx_v112', '["jsj3_sx","U789","p079","apply_01"]', 1, NULL);
