INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'apply', 3, '{"stem": "应用(5)：一个长方形的每条边都向外挪了3米后，新形成长方形的周长为64米，如果原长方形的长是宽的3倍，那么原来长方形的长和宽分别是多少？（7分）"}', '长15米，宽5米', '新周长64→新长宽和=32; 每边外移3m→长宽各增6m→原长宽和=32-6-6=20; 宽=20÷(1+3)=5, 长=5×3=15', 'jsj3_sx_v112', '["jsj3_sx","U789","p079","apply_05"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1026, '数学', '三年级', 'apply', 3, '{"stem": "思维拓展：黄老师买文具发票弄脏了。笔记本5本共165元，钢笔单价75元买1支。(1)黄老师买笔记本花去多少元？(2)一本笔记本比一支钢笔便宜多少元？（10分）"}', '(1)90元 (2)57元', '(1)笔记本总价=165-75×1=90元; (2)笔记本单价=90÷5=18元, 75-18=57元', 'jsj3_sx_v112', '["jsj3_sx","U789","p079","think_01"]', 1, NULL);